export { default as ScrollFloat } from './ScrollFloat.vue';
export type {
  ScrollFloatDirection,
  ScrollFloatEaseFn,
  ScrollFloatEffect,
  ScrollFloatOrder,
  ScrollFloatProps,
  ScrollFloatSplit,
  ScrollFloatToken,
} from './types';

import type { ScrollFloatEaseFn } from './types';

const PI = Math.PI;
const TAU = PI * 2;

const POWERS: Record<string, number> = {
  power0: 0,
  linear: 0,
  power1: 1,
  quad: 1,
  power2: 2,
  cubic: 2,
  power3: 3,
  quart: 3,
  power4: 4,
  quint: 4,
  strong: 4,
};

function bounceOut(t: number): number {
  const n1 = 7.5625;
  const d1 = 2.75;
  if (t < 1 / d1) return n1 * t * t;
  if (t < 2 / d1) {
    const u = t - 1.5 / d1;
    return n1 * u * u + 0.75;
  }
  if (t < 2.5 / d1) {
    const u = t - 2.25 / d1;
    return n1 * u * u + 0.9375;
  }
  const u = t - 2.625 / d1;
  return n1 * u * u + 0.984375;
}

function elasticOut(amplitude = 1, period = 0.3): ScrollFloatEaseFn {
  const p1 = amplitude >= 1 ? amplitude : 1;
  const raw = period / (amplitude < 1 ? amplitude : 1);
  const p3 = (raw / TAU) * (Math.asin(1 / p1) || 0);
  const p2 = TAU / raw;
  return (t) =>
    t === 1 ? 1 : p1 * 2 ** (-10 * t) * Math.sin((t - p3) * p2) + 1;
}

function backOut(overshoot = 1.70158): ScrollFloatEaseFn {
  return (t) => {
    const u = t - 1;
    return u * u * ((overshoot + 1) * u + overshoot) + 1;
  };
}

function outCurve(name: string, args: number[]): ScrollFloatEaseFn | null {
  const power = POWERS[name];
  if (power !== undefined) return (t) => 1 - (1 - t) ** (power + 1);
  switch (name) {
    case 'none':
      return (t) => t;
    case 'expo':
      return (t) => (t >= 1 ? 1 : 1 - 2 ** (-10 * t));
    case 'sine':
      return (t) => Math.sin((t * PI) / 2);
    case 'circ':
      return (t) => Math.sqrt(1 - (t - 1) ** 2);
    case 'back':
      return backOut(args[0]);
    case 'elastic':
      return elasticOut(args[0], args[1]);
    case 'bounce':
      return bounceOut;
    default:
      return null;
  }
}

/**
 * Parses a GSAP-style ease string ('power3.out', 'sine.inOut',
 * 'back.inOut(2)', 'elastic.out(1, 0.45)', 'none'). Unknown names are linear.
 */
export function parseEase(value: string): ScrollFloatEaseFn {
  const match = /^([a-z]\w*)(?:\.(inOut|in|out))?(?:\(([^)]*)\))?$/i.exec(
    value.trim(),
  );
  const name = (match?.[1] ?? 'none').toLowerCase();
  const type = match?.[2] ?? 'out';
  const args = (match?.[3] ?? '')
    .split(',')
    .map((part) => Number.parseFloat(part))
    .filter((n) => Number.isFinite(n));
  const out = outCurve(name, args);
  if (!out) return (t) => t;
  if (name === 'none' || name === 'linear' || name === 'power0') return out;
  if (type === 'in') return (t) => 1 - out(1 - t);
  if (type === 'inOut') {
    return (t) =>
      t < 0.5 ? (1 - out(1 - 2 * t)) / 2 : 0.5 + out(2 * t - 1) / 2;
  }
  return out;
}

import type {
  ScrollFloatEaseFn,
  ScrollFloatEffect,
  ScrollFloatOrder,
} from './types';

export const clamp01 = (value: number): number =>
  Math.min(Math.max(value, 0), 1);

const smoothstep = (from: number, to: number, value: number): number => {
  const k = clamp01((value - from) / (to - from));
  return k * k * (3 - 2 * k);
};

const seeded = (index: number, salt: number): number => {
  const value = Math.sin((index + 1) * 12.9898 + salt * 78.233) * 43758.5453;
  return value - Math.floor(value);
};

const lerp = (from: number, to: number, t: number): number =>
  from + (to - from) * t;

export function getDelays(
  count: number,
  order: ScrollFloatOrder,
  stagger: number,
): number[] {
  const middle = (count - 1) / 2;
  const ranks = Array.from({ length: count }, (_, index) => {
    if (order === 'end') return count - 1 - index;
    if (order === 'center') return Math.abs(index - middle);
    if (order === 'edges') return middle - Math.abs(index - middle);
    return index;
  });
  if (order === 'random') {
    const shuffled = ranks
      .map((_, index) => index)
      .sort((a, b) => seeded(a, 9) - seeded(b, 9));
    shuffled.forEach((target, rank) => {
      ranks[target] = rank;
    });
  }
  const first = count ? Math.min(...ranks) : 0;
  return ranks.map((rank) => (rank - first) * Math.max(0, stagger));
}

export interface FloatLook {
  effect: ScrollFloatEffect;
  sign: number;
  reach: number;
  stretch: number;
  squeeze: number;
  /** Font size of the text in px. */
  size: number;
  count: number;
  colorShift: boolean;
  ease: ScrollFloatEaseFn;
}

/** Paints one piece at linear tween progress `q` (0 = from, 1 = to). */
export function paintFloat(
  piece: HTMLElement,
  index: number,
  q: number,
  look: FloatLook,
) {
  const e = look.ease(q);
  const timing = clamp01(e);
  const { sign, reach, size } = look;
  const middle = (look.count - 1) / 2;
  const edge = middle > 0 ? (index - middle) / middle : 0;
  let opacity: number;
  let x = 0;
  let y = 0;
  let yPercent = 0;
  let rotate = 0;
  let rotateX = 0;
  let scaleX = 1;
  let scaleY = 1;
  let blur = 0;
  let perspective = 0;

  if (look.effect === 'flip') {
    rotateX = -90 * sign * (1 - e);
    perspective = size * 4;
    opacity = smoothstep(0.05, 0.55, timing);
  } else if (look.effect === 'scatter') {
    const sx = ((seeded(index, 1) * 2 - 1) * 1.3 - edge * 0.9) * size * reach;
    const sy = sign * (0.35 + seeded(index, 2)) * size * 1.1 * reach;
    const sr =
      (seeded(index, 3) < 0.5 ? -1 : 1) * (40 + seeded(index, 4) * 120);
    const ss = 0.35 + seeded(index, 5) * 0.9;
    x = lerp(sx, 0, e);
    y = lerp(sy, 0, e);
    rotate = lerp(sr, 0, e);
    scaleX = scaleY = lerp(ss, 1, e);
    opacity = smoothstep(0, 0.4, timing);
  } else if (look.effect === 'blur') {
    opacity = lerp(0, 1, e);
    y = lerp(sign * size * 0.3 * reach, 0, e);
    scaleX = scaleY = lerp(1.45, 1, e);
    blur = lerp(size * 0.2, 0, e);
  } else if (look.effect === 'wave') {
    const decay = Math.pow(1 - timing, 2.6);
    const swell = 1 - Math.cos(timing * Math.PI * 2.5) * decay;
    const sway = Math.sin(timing * Math.PI * 2.5) * decay;
    yPercent = lerp(120 * reach * sign, 0, swell);
    scaleY = lerp(look.stretch, 1, swell);
    scaleX = lerp(look.squeeze, 1, swell);
    rotate = -16 * sign * sway;
    opacity = clamp01(timing * 2.5);
  } else {
    opacity = lerp(0, 1, e);
    yPercent = lerp(120 * reach * sign, 0, e);
    scaleY = lerp(look.stretch, 1, e);
    scaleX = lerp(look.squeeze, 1, e);
  }

  const parts: string[] = [];
  if (perspective) parts.push(`perspective(${perspective.toFixed(2)}px)`);
  if (yPercent) parts.push(`translate(0%, ${yPercent.toFixed(3)}%)`);
  if (x || y) parts.push(`translate(${x.toFixed(2)}px, ${y.toFixed(2)}px)`);
  if (rotate) parts.push(`rotate(${rotate.toFixed(3)}deg)`);
  if (rotateX) parts.push(`rotateX(${rotateX.toFixed(3)}deg)`);
  if (scaleX !== 1 || scaleY !== 1) {
    parts.push(`scale(${scaleX.toFixed(4)}, ${scaleY.toFixed(4)})`);
  }
  piece.style.transform = parts.join(' ');
  piece.style.opacity = opacity >= 1 ? '' : Math.max(0, opacity).toFixed(3);
  piece.style.filter = blur > 0.01 ? `blur(${blur.toFixed(2)}px)` : '';
  if (look.colorShift) {
    piece.style.setProperty(
      '--scroll-float-mix',
      (1 - smoothstep(0.5, 1, timing)).toFixed(3),
    );
  }
}

export function preparePiece(piece: HTMLElement, look: FloatLook) {
  piece.style.willChange =
    look.effect === 'blur'
      ? 'opacity, transform, filter'
      : 'opacity, transform';
  if (look.effect === 'flip') {
    piece.style.transformOrigin = `50% 50% ${(-look.size * 0.55 * look.reach).toFixed(2)}px`;
    piece.style.backfaceVisibility = 'hidden';
  } else if (look.effect === 'float') {
    piece.style.transformOrigin = look.sign > 0 ? '50% 0%' : '50% 100%';
  } else if (look.effect === 'wave') {
    piece.style.transformOrigin = look.sign > 0 ? '50% 100%' : '50% 0%';
  } else {
    piece.style.transformOrigin = '50% 50%';
  }
}

export function resetPiece(piece: HTMLElement) {
  piece.style.transform = '';
  piece.style.opacity = '';
  piece.style.filter = '';
  piece.style.willChange = '';
  piece.style.transformOrigin = '';
  piece.style.backfaceVisibility = '';
  piece.style.removeProperty('--scroll-float-mix');
}

export interface ScrollGeometry {
  top: number;
  height: number;
  view: number;
  scroll: number;
  maxScroll: number;
}

function edgeOffset(token: string, size: number): number {
  const match =
    /^([a-z]+|-?[\d.]+%?(?:px)?)((?:[+-]=-?[\d.]+(?:%|px)?)?)$/.exec(token);
  if (!match) return 0;
  const [, base = '', shift = ''] = match;
  let value: number;
  if (base === 'top' || base === 'left') value = 0;
  else if (base === 'center') value = size / 2;
  else if (base === 'bottom' || base === 'right') value = size;
  else if (base.endsWith('%')) value = (Number.parseFloat(base) / 100) * size;
  else value = Number.parseFloat(base) || 0;
  if (shift) {
    const raw = shift.slice(2);
    let amount = Number.parseFloat(raw) || 0;
    if (raw.endsWith('%')) amount = (amount / 100) * size;
    value += shift.startsWith('+') ? amount : -amount;
  }
  return value;
}

/** Resolves a ScrollTrigger-style position ("center bottom+=50%", "clamp(bottom bottom-=40%)", "+=300"). */
export function resolvePosition(
  position: string,
  geo: ScrollGeometry,
  relativeTo = 0,
): number {
  let source = position.trim();
  let clamped = false;
  const clampMatch = /^clamp\((.*)\)$/.exec(source);
  if (clampMatch) {
    clamped = true;
    source = (clampMatch[1] ?? '').trim();
  }
  let value: number;
  if (/^[+-]=/.test(source)) {
    const amount = Number.parseFloat(source.slice(2)) || 0;
    value = relativeTo + (source.startsWith('+') ? amount : -amount);
  } else {
    const [triggerEdge = 'top', scrollerEdge = 'bottom'] = source.split(/\s+/);
    value =
      geo.top +
      edgeOffset(triggerEdge, geo.height) -
      edgeOffset(scrollerEdge, geo.view);
  }
  return clamped ? Math.min(Math.max(value, 0), geo.maxScroll) : value;
}

export function clampToScroll(position: string): string {
  return position.startsWith('clamp(') ? position : `clamp(${position})`;
}

export function progressBetween(
  scroll: number,
  start: number,
  end: number,
): number {
  if (end <= start) return scroll >= start ? 1 : 0;
  return clamp01((scroll - start) / (end - start));
}

export type ScrollFloatEffect = 'float' | 'flip' | 'scatter' | 'blur' | 'wave';
export type ScrollFloatSplit = 'chars' | 'words';
export type ScrollFloatDirection = 'up' | 'down';
export type ScrollFloatOrder = 'start' | 'end' | 'center' | 'edges' | 'random';
export type ScrollFloatEaseFn = (t: number) => number;

export interface ScrollFloatProps {
  /** Text to animate. Leave it out to animate the default slot as one piece. */
  text?: string;
  /** Element that scrolls. `undefined` uses the window; `null` waits for the element. */
  scrollContainer?: HTMLElement | null;
  /** Extra classes on the text. */
  textClass?: string;
  /** How the pieces arrive. */
  effect?: ScrollFloatEffect;
  /** Animate each letter or each word. */
  splitBy?: ScrollFloatSplit;
  /** Come in from below (`up`) or from above (`down`). */
  direction?: ScrollFloatDirection;
  /** Which pieces go first. */
  order?: ScrollFloatOrder;
  /** Color the pieces start in before settling to the text color. */
  fromColor?: string;
  /** Length of each piece's animation, relative to the stagger. */
  animationDuration?: number;
  /** GSAP-style ease, such as 'back.inOut(2)' or 'elastic.out(1, 0.45)'. */
  ease?: string;
  /** Scroll position where the animation starts (ScrollTrigger syntax). */
  scrollStart?: string;
  /** Scroll position where the animation ends (ScrollTrigger syntax). */
  scrollEnd?: string;
  /** Delay between pieces, relative to the duration. */
  stagger?: number;
  /** How far the pieces travel, 120 being the default reach. */
  distance?: number;
  /** How tall the pieces are stretched while they float in. */
  stretch?: number;
  /** Seconds the animation takes to catch up with the scroll. */
  smoothing?: number;
  class?: string;
}

export type ScrollFloatToken =
  | { kind: 'space'; value: string }
  | { kind: 'word'; value: string; chars: string[] };
